473	    // Counts owners, not shapes: a body with several shapes inside the rect counts once.
474	    std::vector<PhysicsBody*> bodies;
475	    cpSpaceBBQuery(_space,
476	                   PhysicsHelper::rect2cpbb(rect),
477	                   makeCategoryFilter(categoryMask),
478	                   collectBody,
479	                   &bodies);
480	
481	    return static_cast<int>(bodies.size());
