484	bool PhysicsWorldQuery::isPointOccupied(const Vec2& point, unsigned int categoryMask)
485	{
486	    // An uninitialised facade knows of no shapes, so it cannot affirm occupancy.
487	    if (!_initialized || _space == nullptr)
488	    {
489	        return false;
490	    }
491	
492	    // Max distance 0 keeps this to the shapes the point is actually inside of.
493	    cpShape* shape = cpSpacePointQueryNearest(_space,
494	                                              PhysicsHelper::point2cpv(point),
495	                                              0.0f,
496	                                              makeCategoryFilter(categoryMask),
497	                                              nullptr);
498	
499	    return shape != nullptr;
